        # Actually, for topological sort, we just need u before v
        # The consecutiveness is checked separately
        if v != p[u] and not any(candidate == v for candidate in graph[u]):
            graph[u].append(v)
            in_degree[v] += 1

    # Kahn's algorithm
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)

        new_zero = False
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
