def solution(data):
    lines = data.strip().split('\n')

    n, k = map(int, lines[0].split())

    p = [0] * (n + 1)
    parts = lines[1].split()
    for i in range(1, n + 1):
        p[i] = int(parts[i - 1])

    special = []
    for i in range(k):
        special.append(tuple(map(int, lines[2 + i].split())))

    # Check if special pairs form cycles
    nxt = [0] * (n + 1)
    for u, v in special:
        nxt[u] = v

    def cycle(start):
        visited = set()
        x = start
        while x != 0 and x not in visited:
            visited.add(x)
            x = nxt[x]
        return x != 0

    for u in range(1, n + 1):
        if nxt[u] != 0:
            if cycle(u):
                return "\n0\n"

    # Build graph with all constraints
    g = [[] for _ in range(n + 1)]
    indeg = [0] * (n + 1)

    for i in range(1, n + 1):
        if p[i] != 0:
            g[p[i]].append(i)
            indeg[i] += 1

    for u, v in special:
        if v not in g[u]:
            g[u].append(v)
            indeg[v] += 1

    qin = [i for i in range(1, n + 1) if indeg[i] == 0]
    res = []

    while qin:
        u = qin.pop(0)
        res.append(u)
        for v in g[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                qin.append(v)

    if len(res) < n:
        return "\n0\n"

    # Verify special pairs are consecutive
    pos = {x: i for i, x in enumerate(res)}
    for u, v in special:
        if pos[v] != pos[u] + 1:
            return "\n0\n"

    return "\n".join(map(str, res)) + "\n"
