    # For GP: arr[i] / arr[i-1] = arr[1] / arr[0] for all i
    # Cross multiply: arr[i] * arr[0] == arr[i-1] * arr[1]
    for i in range(1, n):
        if arr[i] * arr[0] != arr[i - 1] * arr[1]:
            return False

    return True


