import sys
from collections import deque

def solution(input_data):
    lines = input_data.strip().split('\n')
    if len(lines) == 0:
        return ""

    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = map(int, parts)
            adj[u].append(v)
            adj[v].append(u)

    # Strategy: Build spanning tree, find back edges that create valid cycles
    visited = {1}
    parent = {1: 0}
    tree_edges = set()
    back_edges = []
    queue = deque([1])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                parent[v] = u
                tree_edges.add((min(u, v), max(u, v)))
                queue.append(v)
            elif v != parent[u]:
                edge = (min(u, v), max(u, v))
                if edge not in tree_edges:
                    back_edges.append(edge)

    def get_tree_path(u, target):
        path = []
        curr = u
        while curr and curr != target:
            if curr == 0:
                return None
            path.append(curr)
            curr = parent[curr]
        return path

    cycles = []

    for u, v in back_edges:
        if u == v:
            continue

        path_u = get_tree_path(u, 0) or []
        path_v = get_tree_path(v, 0) or []

        if not path_u or not path_v:
            continue

        # Find paths to root
        lca_idx = 0
        for i in range(max(len(path_u), len(path_v)) - 1, -1, -1):
            if i < len(path_u) and i < len(path_v) and path_u[i] == path_v[i]:
                lca_idx = i
            else:
                break

        idx_u = lca_idx
        idx_v = lca_idx

        if idx_u < len(path_u) and idx_v < len(path_v):
            # Build cycle
            common = path_u[:idx_u+1][::-1]
            non_common_u = path_u[idx_u+1:][::-1]
            non_common_v = path_v[idx_v+1:][::-1]

            cycle = non_common_u + [path_v[idx_v]]
            cycle.extend(non_common_v)
            cycle.extend(common)

            cycle = path_u[:idx_u][::-1] + path_v[idx_v:idx_v+1][::-1]

            if cycle:
                cycle.sort()
                idx_v = max(len(path_u), len(path_v)) - 1 - lca_idx

        # Find cycle using parent pointers only
        curr = u
        cycle_nodes = [curr]
        while parent[curr] and curr != v:
            curr = parent[curr]
            if curr == v:
                break
            cycle_nodes.append(curr)

        if curr == v:
            cycle = cycle_nodes + [v]
            if len(cycle) >= 3 and len(cycle) % 3 != 0:
                cycles.append(cycle)
            if len(cycles) >= k:
                break

    if len(cycles) >= k:
        result = ["CYCLES"]
        for c in cycles[:k]:
            result.append(str(len(c)))
            result.append(" ".join(map(str, c)))
        return "\n".join(result)

    # Long path
    target_len = n // k
    best_path = []

    def dfs_path(start):
        nonlocal best_path
        visited = {start}
        stack = [(start, [start])]
        best_len = 0

        while stack:
            u, path = stack.pop()
            if len(path) > best_len:
                best_len = len(path)
                best_path = path[:]

            for v in adj[u]:
                if v not in visited:
