def solution(data):
    lines = data.strip().split('\n')
    if not lines or len(lines) < 1:
        return '0'

    n, m = map(int, lines[0].split())
    event_lines = lines[1:n+1] if n+1 <= len(lines) else []

    if not event_lines:
        return '0'

    # Parse into segments (between type 1 events)
    segments = []
    current_segment = []

    for line in event_lines:
        if not line.strip():
            continue
        parts = line.split()
        if parts[0] == '1':
            if current_segment:
                segments.append(current_segment)
                current_segment = []
        else:
            friend = parts[1]
            current_segment.append(friend)

    if current_segment:
        segments.append(current_segment)

    if not segments:
        return '0'

    # Build conflict graph - friends in same segment conflict
    # Mapping friend name -> index
    all_friends = set()
    for seg in segments:
        all_friends.update(seg)

    friend_to_idx = {f: i for i, f in enumerate(all_friends)}
    m_actual = len(friend_to_idx)

    # Build adjacency: adj[i] is bitmask of friends that conflict with friend i
    adj = [0] * m_actual
    for seg in segments:
        if not seg:
            continue
        indices = [friend_to_idx[f] for f in seg]
        n_seg = len(indices)
        for i in range(n_seg):
            for j in range(i + 1, n_seg):
                adj[indices[i]] |= (1 << indices[j])

    # Find maximum independent set using DFS with memoization
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(idx, mask):
        # idx: next friend to consider (0 to m_actual-1)
        # mask: bitmask of already selected friends
        if idx == m_actual:
            return bin(mask).count('1')

        # Option 1: Don't include friend idx
        res = dp(idx + 1, mask)

        # Option 2: Include friend idx if not already in mask and no conflicts
        if not (mask & (1 << idx)) and (adj[idx] & mask) == 0:
            res = max(res, 1 + dp(idx + 1, mask | (1 << idx)))

        return res

    return str(dp(0, 0))
