    matrix = lines[1:]

    def can_form_palindrome(s):
        """Check if string can form a palindrome (reordered)"""
        counts = {}
        for c in s:
            counts[c] = counts.get(c, 0) + 1
        odd_count = sum(1 for v in counts.values() if v % 2 == 1)
        return odd_count <= 1

    count = 0

    # Try all possible submatrices
    for i1 in range(n):  # Start row (0-indexed)
        for i2 in range(i1, n):  # End row (inclusive)
            for j1 in range(m):  # Start column (0-indexed)
                for j2 in range(j1, m):  # End column (inclusive)

                    # Check all rows in the submatrix can form palindromes
                    valid = True
                    for i in range(i1, i2 + 1):
                        if not can_form_palindrome(matrix[i][j1:j2+1]):
                            valid = False
                            break

                    if not valid:
