import random
import heapq

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Parse costs - A_{i,j} is cost for city i to build rail to city j
    cost_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        row = list(map(int, lines[i+1].split()))
        idx = 0
        for j in range(n):
            if j != i:
                cost_matrix[i][j] = row[idx]
                idx += 1

    # Build preference lists (lower cost = higher preference)
    prefs = []
    for i in range(n):
        prefs.append(sorted(range(n), key=lambda x: cost_matrix[i][x]))

    # If n is odd, impossible to form pairs
    if n % 2 != 0:
        return '\n'.join(['-1'] * n)

    def is_stable(matching):
        """Check if the matching is stable"""
        for i in range(n):
            partner = matching[i]
            # Try to find any blocking pair
            for j in range(n):
                if i == j:
                    continue
                # j is not matched with i
                if matching[j] != i:
                    # i prefers j over current partner
                    if cost_matrix[i][j] < cost_matrix[i][partner]:
                        # j prefers i over current partner
                        if cost_matrix[j][i] < cost_matrix[j][matching[j]]:
                            return False
        return True

    def generate_random_matching():
        """Generate a random perfect matching"""
        matching = [-1] * n
        used = [False] * n

        while True:
            matched_count = sum(1 for x in matching if x != -1)
            if matched_count == n:
                break
            if all(used):
                return None

            # Find a free city
            free_city = -1
            for i in range(n):
                if not used[i]:
                    free_city = i
                    break

            if free_city == -1:
                return None

            # Try random pairings for remaining free cities
            free_cities = [i for i in range(n) if not used[i]]
            if len(free_cities) == 0:
                return None

            # Take two free cities and pair them randomly
            idx1 = random.randint(0, len(free_cities) - 1)
            city1 = free_cities[idx1]

            for i in range(len(free_cities) - 1):
                idx2 = random.randint(i + 1, len(free_cities) - 1)
                city2 = free_cities[idx2]

                for k in range(len(free_cities)):
                    if free_cities[k] in [city1, city2]:
                        free_cities.pop(k)
                        break

                # Pair them
                matching[city1] = city2
                matching[city2] = city1
                used[city1] = True
                used[city2] = True

        return matching

    def fix_matching(matching):
        """Try to improve matching by checking local stability"""
        improved = False

        for i in range(n):
            if matching[i] == -1:
                continue

            for j in range(n):
                if i == j:
                    continue
                if matching[j] != i:
                    # Check if both would prefer to switch
                    if cost_matrix[i][j] < cost_matrix[i][matching[i]] and \
                       cost_matrix[j][i] < cost_matrix[j][matching[j]]:
                        # Propose and switch
                        matching[i] = j
                        matching[j] = i

        return matching

    # Try multiple random matchings
    for _ in range(2000):
        matching = generate_random_matching()
        if matching is None:
            continue

        # Try to fix stability
        for _ in range(100):
            matching = fix_matching(matching.copy())

        if is_stable(matching):
            return '\n'.join(map(str, [m + 1 if m != -1 else -1 for m in matching]))

    return '\n'.join(['-1'] * n)


if __name__ == "__main__":
    test = "4\n35 19 20\n76 14 75\n23 43 78\n14 76 98"
    print(solution(test))
