    # Precompute all pairs shortest paths using BFS
    dist_matrix = {}
    for start in range(1, n + 1):
        dist = bfs(start)
        for end in range(1, n + 1):
            if dist[end] != -1:
                dist_matrix[(start, end)] = dist[end]

    max_total = -1
    best_sequence = None

    cities = list(range(1, n + 1))

    # Try all permutations of 4 distinct cities
    for perm in permutations(cities, 4):
