    q = deque(sorted([i for i in range(1, n + 1) if in_degree[i] == 0]))
    result = []

    while q:
        node = q.popleft()
        result.append(node)

        new_zeros = []
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
