        left_size = root_idx - in_l

        # Nodes in left subtree (in-order) should be pre-labels [pre_l+1, pre_l+left_size]
        left_expected = set(range(pre_l + 1, pre_l + left_size + 1))
        left_actual = set(result[i] for i in range(in_l, root_idx))

        if left_expected != left_actual:
            return False

        # Right subtree check
        right_pre_start = pre_l + left_size + 1
        right_expected = set(range(right_pre_start, pre_r))

        if left_size + 1 < in_r - in_l:
            right_actual = set(result[i] for i in range(root_idx + 1, in_r))
            if right_expected != right_actual:
                return False

        # Recurse
        new_pre = pre_l + left_size + 1
        return verify_pre_in(new_pre, pre_r, in_l, root_idx) and verify_pre_in(new_pre, pre_r, root_idx + 1, in_r)

