        for i in range(n):
            # Check if current lantern i can illuminate something to the left
            # (position j where j < i and j >= i - p[i])
            # We can turn i to left if there's something to illuminate

            # First, check if we can illuminate from the left side
            can_illuminate_left = False
            for j in range(i):
                # Lantern j can illuminate i if j turned right and j + p[j] - 1 >= i
                if p[j] >= 1 and j + p[j] - 1 >= i:
                    can_illuminate_left = True
                    break

            # Check if we can illuminate from the right side
            can_illuminate_right = False
            for j in range(i + 1, n):
                # Lantern j can illuminate i if j turned left and j - p[j] <= i
                if p[j] >= 1 and j - p[j] <= i:
                    can_illuminate_right = True
                    break

            # Determine direction for lantern i
            # Strategy: Try to turn i to a direction that helps illuminate future/lower lanterns
            # If we can be illuminated from left, turn right to help illuminate more to the right
            # If we can be illuminated from right, turn left to help illuminate more to the left

            # Greedy approach: prefer direction that maximizes future illumination potential
            if can_illuminate_left and i - p[i] >= 0:
                ans[i] = 'R'  # Turn right when can be illuminated from right
            elif can_illuminate_right and i + p[i] < n:
                ans[i] = 'L'  # Turn left when can be illuminated from left
            elif i + p[i] < n:
                ans[i] = 'L'  
            else:
                ans[i] = 'R'  # No clear benefit, choose right as default

            # Mark if lantern i is illuminated
            if can_illuminate_left or can_illuminate_right:
                lit[i] = True

        # If not all lanterns are illuminated with this greedy approach, try alternate
        if not all(lit):
            # Try other approach: process in alternating patterns
            lit_false = any(not x for x in lit)
            if lit_false:
                # Reset and try a left-right-R-RL pattern
