                for j in range(i + 1, n):
                    if p[j] >= 1 and j - p[j] <= i:
                        can_right = True
                        break

                if can_left:
                    ans2[i] = 'R'
                elif can_right:
                    ans2[i] = 'L'
                elif i > 0 or i + p[i] < n - 1:
                    ans2[i] = 'L'
                else:
                    ans2[i] = 'R'

            # Verify
