def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        edges.append((a, b))

    def crosses(a1, b1, a2, b2):
        if len({a1, b1, a2, b2}) < 4:
            return False

        def count_between(start, end, point):
            if start < end:
                return start < point and point < end
            else:
                return point > start or point < end

        # Two chords (a1,b1) and (a2,b2) cross if endpoints alternate
        # More precisely: one endpoint of second chord is in arc (a1->b1), other is not

        c_between_a1_b1 = count_between(a1, b1, a2)
        d_between_a1_b1 = count_between(a1, b1, b2)

        if c_between_a1_b1 != d_between_a1_b1 and c_between_a1_b1 != d_between_a1_b1:
            return False

        x_between = count_between(a1, b1, a2)
        y_between = count_between(a1, b1, b2)

        return x_between != y_between

    num_vars = 2 * m
    adj = [[] for _ in range(num_vars)]
    conflict = [[False] * m for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            a1, b1 = edges[i]
            a2, b2 = edges[j]
            if crosses(a1, b1, a2, b2):
                conflict[i][j] = conflict[j][i] = True
                # 2-SAT constraints
                # i_in -> j_out, i_out -> j_in, j_in -> i_out, j_out -> i_in
                adj[2*i].append(2 * j + 1)
                adj[2*i + 1].append(2 * j)
                adj[2*j].append(2 * i + 1)
                adj[2*j + 1].append(2 * i)

    visited = [False] * num_vars
    comp = [-1] * num_vars
    order = []

    def dfs1(v):
        visited[v] = True
        for w in adj[v]:
            if not visited[w]:
                dfs1(w)
        order.append(v)

    for i in range(num_vars):
        if not visited[i]:
            dfs1(i)

    def dfs2(v, c):
        comp[v] = c
        comp_stack.append(v)
        for w in adj[v]:
            if comp[w] == -1:
                dfs2(w, c)
            else:
                if comp[w] == 0:
                    return False

    stack = []
    mst = {}
    low = {}
    id_counter = [0]
    scc_count = [0]

    def tarjan(v):
        stack.append(v)
        low[v] = id_counter[0]
        mst[v] = id_counter[0]
        id_counter[0] += 1
        for w in adj[v]:
            if w not in mst:
                tarjan(w)
                low[v] = min(low[v], low[w])
            elif w in stack:
                low[v] = min(low[v], mst[w])

        if low[v] == mst[v]:
            scc_count[0] += 1
            while True:
                w = stack.pop()
                comp[w] = scc_count[0] - 1
                if w == v:
                    break

    for v in range(num_vars):
        if v not in mst:
            tarjan(v)

    for i in range(m):
        if comp[2*i] == comp[2*i + 1]:
            return "Impossible"

    result = []
    for i in range(m):
        if comp[2*i] < comp[2*i + 1]:
            result.append('i')
        else:
            result.append('o')

    return ''.join(result)
